function minRewrites(s: string, t: string): number {
  const a = [...s].sort(), b = [...t].sort();
  let i = 0, j = 0, shared = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) { shared++; i++; j++; }
    else if (a[i] < b[j]) i++;
    else j++;
  }
  return t.length - shared;
}

