class Solution:
    def minRewrites(self, s: str, t: str) -> int:
        a, b = sorted(s), sorted(t)
        i = j = shared = 0
        while i < len(a) and j < len(b):
            if a[i] == b[j]:
                shared += 1
                i += 1
                j += 1
            elif a[i] < b[j]:
                i += 1
            else:
                j += 1
        return len(t) - shared

