function minRewrites(s: string, t: string): number {
  const need = new Array(26).fill(0);
  for (let i = 0; i < s.length; i++) need[s.charCodeAt(i) - 97]++;
  let steps = 0;
  for (let i = 0; i < t.length; i++) {
    const c = t.charCodeAt(i) - 97;
    if (need[c] > 0) need[c]--;
    else steps++;
  }
  return steps;
}

